import{_ as t,o as a,c as s,ag as r}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Week 10 — Supply Chain and Secure Code","description":"","frontmatter":{"source":"weeks/10-supply-chain/README.md"},"headers":[],"relativePath":"weeks/10-supply-chain/index.md","filePath":"weeks/10-supply-chain/index.md"}'),n={name:"weeks/10-supply-chain/index.md"};function o(i,e,d,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="week-10--supply-chain-and-secure-code" tabindex="-1">Week 10 — Supply Chain and Secure Code <a class="header-anchor" href="#week-10--supply-chain-and-secure-code" aria-label="Permalink to &quot;Week 10 — Supply Chain and Secure Code&quot;">​</a></h1><blockquote><p>Working code isn&#39;t secure code, and most of what you ship is code you didn&#39;t write: verify what you install, scan what you wrote, look for secrets in the history and not just the files, and keep them out of the agent&#39;s reach.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>Reading and reading response on Canvas · submit the week 9 assignment (the Seminar opens with its quiz) · your <strong>PR-round PR</strong> is open on your target fork · graduate presentation: post one question (<a href="./../../graduate/paper-presentations.html#questions-from-the-class">how</a>)</td></tr><tr><td><strong>Seminar</strong></td><td>Due-date quiz on the week 9 assignment (7 min, 🔴 AI off) · talk: insecure-but-working code, slopsquatting, dependency confusion, secrets in agent workflows, provenance and SBOMs, the 2025–26 incidents (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-10.html" target="_blank" rel="noreferrer">slides</a>) · case jigsaw (B1, B4, B5, B6) or a graduate paper · demo: checking an agent&#39;s package suggestions; a secret a file scan misses · Lab preview</td></tr><tr><td><strong>Lab</strong></td><td><a href="./lab.html#lab--scan-and-fix-75-min">Scan and fix</a> on <code>roomly</code> and your team fork: CodeQL or Semgrep, <code>npm audit</code> (development versus runtime), package-name checks, a secret scan of the whole history; start fixing one finding with a regression test. <strong>Checkoff:</strong> one triaged finding, with evidence</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Default 11:59 pm the night before: the <a href="./lab.html#assignment--a-security-review-of-your-teams-work">assignment</a> (your fix with its regression test; your part of the team&#39;s security review) · <strong>the PR round closes</strong>: your team&#39;s reviews and decisions, and your answers to the review of your PR</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: scanners, triage support, the fix and its test · 🟡 AI limited: <code>THREAT_MODEL.md</code> (an AI may brainstorm attacks; the analysis is yours) · 🔴 AI off: PR-round review comments and decisions, the quiz, the reading response</td></tr><tr><td><strong>Reading</strong></td><td>Vero et al., <a href="https://arxiv.org/abs/2502.11844" target="_blank" rel="noreferrer">&quot;BaxBench: Can LLMs Generate Correct and Secure Backends?&quot;</a> (2025)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words on Canvas, 🔴 AI off, before the Seminar (<a href="#reading">prompt</a>)</td></tr><tr><td><strong>Team project</strong></td><td><strong>The PR round</strong> (<a href="./../../project/pr-round.html#week-10-review-respond-decide">rules</a>): your team&#39;s first review of each received PR by the end of this Lab; a decision on each before the week 11 Seminar. The security review feeds M2&#39;s security row</td></tr><tr><td><strong>Graduate track</strong></td><td>BaxBench (Vero et al.) or LiCoEval (Xu et al.), if scheduled (<a href="./../../graduate/paper-presentations.html#the-papers">papers</a>); interim results are due before the week 12 Seminar</td></tr><tr><td><strong>Time</strong></td><td>Meetings 2.5 h · outside about 6 h (CS [5xxx]: 7.5 h): reading 45 min, assignment 3.5 h · plus about 2 h for the PR round</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Explain why passing functional tests doesn&#39;t establish security, and write an <strong>exploit test</strong>: the attacker&#39;s request, and the response the specification requires.</li><li>Triage static analysis and dependency audits: development-only versus runtime exposure, reachable versus unreachable, and never a fix you haven&#39;t read.</li><li>Check a package before an agent installs it, and explain <a href="./../../resources/glossary.html#slopsquatting">slopsquatting</a> and dependency confusion.</li><li>Scan a repository&#39;s whole history for secrets, and know what to do when you find one.</li><li>Generate a software bill of materials (SBOM), check registry signatures and provenance, and say what each proves and what it doesn&#39;t.</li><li>Write a security review of your team&#39;s contributions: an updated threat model and a findings table with a decision for every finding.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Minutes</th><th>What happens</th></tr></thead><tbody><tr><td>Due-date quiz</td><td>7</td><td>On the week 9 assignment (<a href="./../../assessment/quizzes.html">quizzes</a>), 🔴 AI off</td></tr><tr><td>Concept talk</td><td>25</td><td>Working versus secure; where dependencies come from and how names get hijacked; secrets in agent setups; provenance and SBOMs (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-10.html" target="_blank" rel="noreferrer">slides</a>)</td></tr><tr><td>Case jigsaw or paper</td><td>20</td><td>Cases <a href="./../../resources/case-studies.html#using-these-in-class">B1, B4, B5, B6</a>, or a graduate presentation</td></tr><tr><td>Live demo</td><td>10</td><td>An agent suggests packages and we check each name; then a deleted key that a file scan misses and a history scan finds</td></tr><tr><td>Lab preview</td><td>5</td><td>Start CodeQL first; the checkoff is one triaged finding</td></tr></tbody></table><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>In the <a href="./lab.html#lab--scan-and-fix-75-min">Lab</a> you scan your own <code>roomly</code> repository and your team fork: static analysis, the dependency audit (and how little actually ships), the names an agent suggests installing, and secrets anywhere in git history; then you fix one finding with a regression test. The <a href="./lab.html#assignment--a-security-review-of-your-teams-work">assignment</a> turns this into your part of a security review of your team&#39;s contributions.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p><strong>Vero et al., <a href="https://arxiv.org/abs/2502.11844" target="_blank" rel="noreferrer">&quot;BaxBench&quot;</a></strong> (2025; free on arXiv). 392 backend tasks, each checked with functional tests <strong>and</strong> end-to-end exploits. The best model was correct 62% of the time, and about half of the correct programs were exploitable (<a href="./../../resources/case-studies.html#b6-baxbench-working-but-exploitable">case B6</a>).</p><p><strong>Reading response prompt</strong> (150–250 words, 🔴 AI off): State the main finding with two numbers, and why the benchmark needs exploits as well as functional tests. What can an end-to-end exploit find that a static analyzer can&#39;t, and what might the exploits miss? End with one exploit test you&#39;d write for <code>roomly</code>&#39;s booking API (the request, and what the spec says should happen), and one question for the Seminar.</p><p>More: <a href="./../../resources/reading-list.html#week-10--supply-chain-and-secure-code">reading list, week 10</a> and the <a href="./../../resources/case-studies.html#supply-chain-and-insecure-code">supply-chain case studies</a>.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>&quot;The tests pass&quot; and &quot;it&#39;s secure&quot; are different measurements.</strong> Security-related agentic PRs, about 4% of 33,000+, merge less often and wait longer for review (<a href="https://arxiv.org/abs/2601.00477" target="_blank" rel="noreferrer">Siddiq et al.</a>). Security review is its own step.</li><li><strong>An exploit test</strong> is the attacker&#39;s request plus the response the spec requires (<code>403</code>, data unchanged). Scanners find dangerous patterns; missing permission checks need someone thinking like an attacker.</li><li><strong>Slopsquatting.</strong> Models invented package names in 21.7% of open-model and 5.2% of commercial-model outputs in a 2025 study, and 43% of invented names recurred in all ten repeat runs, which makes them predictable to register. Frontier models still invented 4.6–6.1% in 2026 (<a href="./../../resources/case-studies.html#b5-slopsquatting-packages-that-dont-exist">case B5</a>). Check existence, age, use and source before anything installs.</li><li><strong>Dependency confusion.</strong> An internal package name nobody claimed on the public registry can be published there with a higher version, and a misconfigured install picks it. Controls: scoped names mapped to your registry, lockfiles with integrity hashes, <code>npm ci</code>.</li><li><strong>Install scripts run before you&#39;ve read anything.</strong> Shai-Hulud compromised 500+ npm packages (<a href="./../../resources/case-studies.html#b1-shai-hulud-a-self-replicating-npm-worm">B1</a>); Nx&#39;s poisoned releases used the AI CLIs already on developers&#39; machines to hunt for secrets, leaking 2,349 credentials from 1,079 systems (<a href="./../../resources/case-studies.html#b2-nx-s1ngularity-malware-that-used-your-ai-tools">B2</a>); a 2026 <code>preinstall</code> hook collected <code>.env</code> files, SSH keys and AI tools&#39; configuration (<a href="./../../resources/case-studies.html#b4-malware-that-hunts-for-ai-keys">B4</a>).</li><li><strong>Development dependencies are a different exposure, not none.</strong> <code>roomly</code>&#39;s advisories are all in its testing tools, which don&#39;t ship but do run on your laptop, Codespace and CI. Reachability decides severity.</li><li><strong>Secrets live in history.</strong> A key deleted in a later commit is still in every clone. Scan the whole history; if a real key reached a pushed commit, rotate it first (<a href="./../../resources/troubleshooting.html#i-committed-a-secret">troubleshooting</a>). Agents, and malware, read environment variables, <code>.env</code> files and agent config folders.</li><li><strong>Provenance and SBOMs.</strong> A registry signature shows a package arrived unaltered; a provenance attestation ties a release to the repository and build that made it. Neither shows the code is benign. An SBOM lists what you ship, so &quot;are we affected?&quot; takes a minute.</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li><code>npm audit</code> reports advisories in <code>roomly</code>; <code>npm audit --omit=dev</code> reports none. Who is exposed, and when would it matter?</li><li>Why does the <em>recurrence</em> of hallucinated package names matter more than their rate?</li><li>A teammate pushed a commit adding an API key, then one deleting it. What do you do, in order?</li><li>What does a verified provenance attestation tell you, and what doesn&#39;t it?</li><li>CodeQL finds almost nothing in <code>roomly</code>. Is it secure? What would you do next?</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>No CodeQL</strong> (private repository, no admin rights, analysis unfinished): Semgrep Community Edition or Opengrep locally (<a href="./../../TOOLS.html#tools-by-week">Tool Handout: Tools by week</a>).</li><li><strong>The npm registry is unreachable:</strong> read the lockfile (<code>grep &#39;&quot;hasInstallScript&quot;&#39; package-lock.json</code>, <code>npm ls --all</code>) and audit when it&#39;s back.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Xu et al., <a href="https://arxiv.org/abs/2408.02487" target="_blank" rel="noreferrer">&quot;LiCoEval&quot;</a>: the best of 14 models produced code &quot;strikingly similar&quot; to existing open source in 0.88–2.01% of outputs, and most gave inaccurate license information; a <a href="./../../graduate/paper-presentations.html">graduate seminar</a> paper.</li><li>CISA&#39;s <a href="https://www.cisa.gov/news-events/alerts/2025/09/23/widespread-supply-chain-compromise-impacting-npm-ecosystem" target="_blank" rel="noreferrer">Shai-Hulud alert</a>: audit lockfiles, pin, rotate credentials, require phishing-resistant MFA. UT Austin&#39;s CS 378 gives a session to <a href="https://www.cs.utexas.edu/~witchel/378AC/schedule.html" target="_blank" rel="noreferrer">&quot;using secrets safely with agents&quot;</a>.</li><li>Case <a href="./../../resources/case-studies.html#b3-amazon-q-a-wiper-prompt-ships-in-an-extension">B3</a>: a wiper prompt merged into an extension; review prompts in incoming PRs like code.</li><li>Previous week: <a href="./../09-review-at-scale/">Review at Scale</a>. Next week: <a href="./../11-llm-features/">Building LLM Features</a>.</li></ul>',23)])])}const p=t(n,[["render",o]]);export{g as __pageData,p as default};
